```ts
import type { Camera } from "@babylonjs/lite";
import {
  getViewMatrix,
  getViewProjectionMatrix,
  getEffectiveAspectRatio,
  resolveCameraViewport,
  projectWorldToScreen,
  getCameraPosition,
} from "@babylonjs/lite";

export function labelPosition(
  camera: Camera,
  canvas: HTMLCanvasElement,
  point: { x: number; y: number; z: number }
): { x: number; y: number; visible: boolean } {
  const backingWidth = canvas.width;
  const backingHeight = canvas.height;
  const cssWidth = canvas.clientWidth;
  const cssHeight = canvas.clientHeight;

  const aspect = getEffectiveAspectRatio(camera, backingWidth, backingHeight);
  const view = getViewMatrix(camera);
  const viewProjection = getViewProjectionMatrix(camera, aspect);
  const viewport = resolveCameraViewport(camera, backingWidth, backingHeight);

  const options: {
    viewport: { x: number; y: number; width: number; height: number };
    backingWidth: number;
    backingHeight: number;
    cssWidth: number;
    cssHeight: number;
    worldOrigin?: { x: number; y: number; z: number };
  } = {
    viewport,
    backingWidth,
    backingHeight,
    cssWidth,
    cssHeight,
  };

  if (camera._useFloatingOrigin) {
    options.worldOrigin = getCameraPosition(camera);
  }

  const result = projectWorldToScreen(point, view, viewProjection, options);

  return {
    x: result.cssX,
    y: result.cssY,
    visible: !result.behindCamera && !result.offscreen,
  };
}
```

I wrote `src/label-position.ts` which projects the world point through the camera's view-projection matrices using `projectWorldToScreen`, returning CSS-pixel coordinates (`cssX`/`cssY`) and a `visible` flag that is true when the point is neither behind the camera nor outside the rendered viewport (so points beyond the far plane but still in-frame count as visible, per note 24). The only thing I'm slightly unsure of is whether `canvas.clientWidth`/`clientHeight` is the right source for the CSS size versus reading from `getComputedStyle` — in practice they agree unless the canvas has a CSS `transform: scale()` applied, which would be unusual for a 3D viewer.
